<script setup lang="ts">
import {computed,onMounted,ref} from "vue";
import {ElMessage} from "element-plus";
import {knowledgeApi} from "@/api/knowledge.api";
import {useAuthStore} from "@/stores/auth.store";
import {admissionLabel} from "@/utils/standard-admission";
import KnowledgeSubmitDialog from "./KnowledgeSubmitDialog.vue";
import type {KnowledgeItem} from "@/types/knowledge.types";
const props=withDefaults(defineProps<{readonly?:boolean}>(),{readonly:false});
const auth=useAuthStore();const rows=ref<KnowledgeItem[]>([]);const busy=ref(false);const error=ref("");const detail=ref<KnowledgeItem|null>(null);
const drawer=ref(false);const submitOpen=ref(false);const dialog=ref(false);const action=ref("review");const decision=ref("approve");const reason=ref("");const evidence=ref("");const keyword=ref("");const statusFilter=ref("all");
const filtered=computed(()=>rows.value.filter(r=>(statusFilter.value==='all'||r.publication_status===statusFilter.value||r.review_status===statusFilter.value)&&(!keyword.value||[r.snapshot.claim,r.snapshot.product_category].some(s=>s.includes(keyword.value)))));
const mappingText=ref('{}');const mappingResult=ref<Record<string,any>|null>(null);
async function previewMapping(){if(!detail.value)return;try{mappingResult.value=(await knowledgeApi.action(detail.value.id,'mapping-preview',{expected_version:detail.value.row_version,request_key:crypto.randomUUID(),reason:reason.value||'核对跨范围映射',mapping_rules:JSON.parse(mappingText.value),mapping_version:'explicit-v1'})).data.data as unknown as Record<string,any>;}catch(e:any){error.value=e.response?.data?.error?.message||'映射未完成，请核对JSON和来源';}}
const canReview=computed(()=>auth.primaryRole==='expert'&&auth.hasPermission('knowledge_review')&&detail.value?.created_by!==auth.userId);
const scopeLabel=(state:string)=>({private:'私人',pending:'待审批',approved:'已批准',rejected:'已拒绝'} as Record<string,string>)[state]||state;
const sourceLabel=(state:string)=>({rag_document:'资料文件',task_result:'任务结果',meeting_message:'会议发言',intake_record:'接入材料',standard_revision:'标准修订'} as Record<string,string>)[state]||'来源资料';
const authorityLabel=(state:string)=>({formal_standard:'已发布标准',unpublished_standard:'尚未发布的标准',reviewed_result:'已复核结果',ai_result_draft:'AI结果草稿',meeting_opinion:'会议意见',observed_material:'实际材料',reference_only:'参考资料'} as Record<string,string>)[state]||'待核对性质';
const sourceDomain=(source:{kind:string;authority?:string})=>source.kind==='standard_revision'?(source.authority==='formal_standard'?'正式标准域':'标准待核验域'):source.kind==='rag_document'?'专家资料域':(['task_result','inspection_execution'].includes(source.kind)?'任务证据域':'业务材料域');
async function load(){busy.value=true;try{rows.value=(await(props.readonly?knowledgeApi.published():knowledgeApi.candidates())).data.data;}finally{busy.value=false;}}
async function show(row:KnowledgeItem){detail.value=(await knowledgeApi.detail(row.id)).data.data;drawer.value=true;}
function openAction(value:string){action.value=value;decision.value='approve';reason.value='';evidence.value='';error.value='';mappingText.value='{}';mappingResult.value=null;dialog.value=true;}
async function execute(){if(!detail.value)return;busy.value=true;error.value='';try{const payload:Record<string,unknown>={expected_version:detail.value.row_version,request_key:crypto.randomUUID(),reason:reason.value,evidence_refs:evidence.value.split('\n').map(s=>s.trim()).filter(Boolean)};
  if(['review','sharing'].includes(action.value))payload.decision=decision.value;
  if(action.value==='publish'){payload.mapping_rules=JSON.parse(mappingText.value);payload.mapping_version='explicit-v1';}
  detail.value=(await knowledgeApi.action(detail.value.id,action.value,payload)).data.data;dialog.value=false;await load();ElMessage.success('决定已记录');
  }catch(e:any){error.value=e.response?.data?.error?.message||'操作未完成，请核对状态';}finally{busy.value=false;}}
onMounted(load);
</script>
<template>
<section class="knowledge-panel">
  <header><div><h3>{{ props.readonly?'已确认知识':'知识主张准入' }}</h3><p>{{ props.readonly?'查看已发布的本人或组织知识，按适用条件复用。':'主张核验与共享范围分别决定，发布后才进入已确认知识检索。' }}</p></div><div><el-button @click="load">刷新</el-button><el-button v-if="!props.readonly&&auth.hasPermission('knowledge_candidate_submit')" type="primary" @click="submitOpen=true">提交知识候选</el-button></div></header>
  <div class="filters"><el-input v-model="keyword" placeholder="按知识主张或产品类别查找" clearable class="keyword"/><el-select v-model="statusFilter" placeholder="状态" clearable><el-option label="全部状态" value="all"/><el-option label="待核验" value="candidate"/><el-option label="已核验" value="approved"/><el-option label="未发布" value="unpublished"/><el-option label="发布中" value="publishing"/><el-option label="已发布" value="published"/><el-option label="已撤回 / 隔离" value="withdrawn"/></el-select></div>
  <el-table :data="filtered" v-loading="busy" row-key="id"><el-table-column label="知识主张" min-width="300"><template #default="{row}"><strong>{{ row.snapshot.claim }}</strong><p class="muted">{{ row.snapshot.product_category }} · {{ row.snapshot.applicability }}</p></template></el-table-column><el-table-column label="来源域" width="140"><template #default="{row}"><span>{{ row.source_refs?.length ? sourceDomain(row.source_refs[0]) : '待核对来源' }}</span><p class="muted">{{ row.source_refs?.length || 0 }} 个来源</p></template></el-table-column><el-table-column label="范围" width="120"><template #default="{row}">{{ row.snapshot.requested_scope==='organization'?'组织申请':'本人使用' }}</template></el-table-column><el-table-column label="专业核验" width="110"><template #default="{row}">{{ admissionLabel(row.review_status) }}</template></el-table-column><el-table-column label="共享审批" width="110"><template #default="{row}">{{ scopeLabel(row.sharing_status) }}</template></el-table-column><el-table-column label="发布" width="120"><template #default="{row}">{{ admissionLabel(row.publication_status) }}</template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="show(row)">出处与核对</el-button></template></el-table-column></el-table>
  <KnowledgeSubmitDialog v-model="submitOpen" @submitted="load"/>
  <el-drawer v-model="drawer" title="知识主张、证据与使用范围" size="min(920px,95vw)" append-to-body>
    <template v-if="detail"><h2>{{ detail.snapshot.claim }}</h2><div class="status-strip"><span>专业核验：{{ admissionLabel(detail.review_status) }}</span><span>共享范围：{{ scopeLabel(detail.sharing_status) }}</span><span>发布：{{ admissionLabel(detail.publication_status) }}</span><span>来源域：{{ detail.source_refs?.length ? sourceDomain(detail.source_refs[0]) : '待核对来源' }}</span></div>
      <el-alert v-if="detail.publication_status!=='published'" title="尚不可作为已确认知识使用；资料可以查阅，主张仍需核对。" type="warning" :closable="false"/>
      <h3>适用条件</h3><p>{{ detail.snapshot.applicability }}</p><h3>限制与缺项</h3><p>{{ detail.snapshot.limitations }}</p>
      <h3>原始来源（{{ detail.source_refs.length }}）</h3><article v-for="source in detail.source_refs" :key="`${source.kind}:${source.id}`" class="source-card"><strong>{{ source.metadata?.title || source.kind }}</strong><p class="muted">{{ sourceDomain(source) }} · {{ sourceLabel(source.kind) }} · {{ authorityLabel(source.authority||'') }}</p><blockquote>{{ source.quote || '仅记录出处；没有选取证明主张的原文片段。' }}</blockquote></article>
      <el-collapse v-if="detail.snapshot.qdl"><el-collapse-item title="结构化主张与范围"><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{ JSON.stringify(detail.snapshot.qdl,null,2) }}</pre></el-collapse-item></el-collapse>
      <div v-if="!props.readonly" class="actions"><el-button v-if="canReview&&detail.publication_status==='unpublished'" type="primary" @click="openAction('review')">专业核验</el-button><el-button v-if="auth.hasPermission('knowledge_share_decide')&&detail.snapshot.requested_scope==='organization'&&detail.publication_status==='unpublished'" @click="openAction('sharing')">审批组织使用范围</el-button><el-button v-if="auth.hasPermission('knowledge_publish')&&detail.review_status==='approved'&&detail.publication_status==='unpublished'&&(detail.snapshot.requested_scope==='private'||detail.sharing_status==='approved')" type="primary" @click="openAction('publish')">发布知识</el-button><el-button v-if="['published','publishing','suspended'].includes(detail.publication_status)&&(detail.created_by===auth.userId||auth.hasPermission('knowledge_publish'))" type="danger" plain @click="openAction('withdraw')">撤回知识</el-button><el-button v-if="auth.hasPermission('knowledge_publish')&&detail.jobs?.some(j=>j.status==='failed')" @click="openAction('retry')">重试同步</el-button></div>
      <h3>决策记录</h3><el-table :data="detail.actions"><el-table-column prop="action" label="操作" width="120"/><el-table-column prop="reason" label="核对说明"/><el-table-column prop="created_at" label="时间" width="190"/></el-table>
      <h3>发布与撤回处理</h3><el-table :data="detail.jobs"><el-table-column prop="action" label="处理项"/><el-table-column prop="status" label="状态"/><el-table-column prop="error" label="问题"/></el-table>
    </template>
  </el-drawer>
  <el-dialog v-model="dialog" :title="action==='review'?'知识专业核验':action==='sharing'?'审批组织使用范围':action==='publish'?'发布知识':action==='withdraw'?'撤回知识':'重试同步'" width="650px" append-to-body>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <el-form label-position="top"><el-form-item v-if="['review','sharing'].includes(action)" label="决定"><el-select v-model="decision"><el-option label="同意" value="approve"/><el-option label="退回" value="reject"/><el-option v-if="action==='review'" label="待补充来源或条件" value="needs_information"/><el-option v-if="action==='review'" label="存在分歧" value="dispute"/></el-select></el-form-item><el-form-item label="核对说明或操作原因" required><el-input v-model="reason" type="textarea" :rows="3"/></el-form-item><el-form-item label="专业依据（每行一条，核验通过时必填）"><el-input v-model="evidence" type="textarea" :rows="3"/></el-form-item></el-form>
    <template v-if="action==='publish'&&detail?.snapshot.qdl"><el-form-item label="跨范围实体与关系映射（JSON）"><el-input v-model="mappingText" type="textarea" :rows="5"/></el-form-item><el-button @click="previewMapping">预览映射缺项</el-button><p v-if="mappingResult">{{ mappingResult.status }} · {{ (mappingResult.unmapped_fields||[]).join('；') }}</p></template>
    <template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="reason.trim().length<4" @click="execute">确认并记录</el-button></template>
  </el-dialog>
</section>
</template>
<style scoped>.knowledge-panel{display:flex;flex-direction:column;gap:18px}.knowledge-panel header{display:flex;justify-content:space-between;align-items:start;gap:20px;border-bottom:2px solid var(--el-color-primary);padding-bottom:18px}.knowledge-panel h3{margin:0;font-size:20px}.knowledge-panel header p,.muted{color:var(--el-text-color-secondary);font-size:13px;line-height:1.7}.filters{display:flex;gap:12px;align-items:center}.keyword{max-width:500px}.filters .el-select{width:180px}.source-card{padding:16px;border:1px solid var(--el-border-color);border-left:3px solid var(--el-color-primary);border-radius:6px;margin-bottom:12px}.source-card blockquote{white-space:pre-wrap;line-height:1.8;margin:12px 0}.status-strip{display:flex;gap:18px;flex-wrap:wrap;margin:18px 0;font-size:13px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}@media(max-width:650px){.filters{display:block}.filters .el-select,.keyword{width:100%;max-width:none;margin-bottom:8px}}</style>
